update htmlformentry_html_form set xml_data = '<htmlform>\r\n        <html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n        <head>\r\n        <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n        <title>FICHA RESUMO</title>\r\n          \r\n          <style>\r\n    \r\n            .main{\r\n                display: flex;\r\n                align-items: center;\r\n                flex-direction: column;\r\n                font-size: .9em;\r\n                width: 100%;\r\n            }\r\n    \r\n            .header-box{\r\n                width: 80%;\r\n                background: #1aac9b;\r\n                padding: 1px !important;\r\n                color: #fff;\r\n                box-shadow: 0 0 .3em #000;\r\n                margin-bottom: 10px;\r\n            }\r\n            \r\n            .content {\r\n                display: flex;\r\n                flex-flow: row wrap;\r\n                width: 80%;\r\n                border: 1px solid #1aac9b;\r\n                box-shadow: 0 0 .3em #000;\r\n            }\r\n    \r\n            .line-break {\r\n                width: 100%;\r\n            }\r\n    \r\n            .header, .space-between{\r\n                display: flex;\r\n                flex-flow: row wrap;\r\n                justify-content: space-between;\r\n                align-content: space-between;\r\n                width: 100%\r\n            }\r\n    \r\n            .header-data{\r\n              border: 1px solid #1aac9b;\r\n              margin-bottom: 10px !important;\r\n              padding: 0px 10px 0px 10px;\r\n              box-shadow: 0 0 .1em #000;\r\n              margin: 10px 10px;\r\n              background: #dedede\r\n            }\r\n    \r\n            .header-info{\r\n              border: 1px solid #1aac9b;\r\n              padding: 0px 10px 0px 10px;\r\n              box-shadow: 0 0 .1em #000;\r\n              margin: 10px 10px;\r\n              background: #dedede\r\n            }\r\n    \r\n            .header-box h2{\r\n               padding-left: 10px;\r\n               text-shadow: 0 0 .3em #000;\r\n            }\r\n    \r\n    \r\n            .header-info h3{\r\n              text-align: center;\r\n            }\r\n    \r\n            input[type=\"text\"]{\r\n                width: 150px;\r\n                margin-bottom: 4px;\r\n            }\r\n    \r\n            .input-size input[type=\"text\"]{\r\n                width: 50px !important;\r\n            }\r\n    \r\n            .input-size-2 input[type=\"text\"]{\r\n                width: 70px !important;\r\n            }\r\n    \r\n            p select {\r\n                width: 150px;\r\n                margin-bottom: 4px;\r\n            }\r\n    \r\n            .base-margin {\r\n                margin-left: 15px;\r\n            }\r\n    \r\n            .submit-btn {\r\n                flex: 1;\r\n                margin: 10px 15px;\r\n            }\r\n    \r\n             .submit-btn input{\r\n               color: #fff;\r\n               background: #1aac9b;\r\n               padding: 8px;\r\n               width: 12.8em;\r\n               font-weight: bold;\r\n               text-shadow: 0 0 .3em black;\r\n               font-size: 9pt;\r\n               border-radius: 5px 5px;\r\n            }\r\n    \r\n            .label-tag {\r\n               color: #fff;\r\n               background: #1aac9b;\r\n               padding: 7px;\r\n               font-weight: bold;\r\n               text-shadow: 0 0 .3em black;\r\n               font-size: 9pt;\r\n               border-radius: 5px 5px;\r\n               width: 100%;\r\n               display: inline-block;\r\n            }\r\n    \r\n            .input-with-size input[type=\"text\"]{\r\n                width : 50px !important;\r\n            }\r\n    \r\n            .input-with-size-lg input[type=\"text\"]{\r\n                width : 400px !important;\r\n            }\r\n    \r\n            .hasDatepicker{\r\n                width : 80p