        let dataConsulta = new Date(valorDataConsulta);\r\n            var currentDate = new Date();\r\n\r\n\r\n               //Compara se a data da proxima é menor que a data de levantamento\r\n              if (currentDate &lt;=  dataConsulta) {\r\n                  alert(\'A data de abertura do processo deve ser menor ou igual a data corrente.\');\r\n                  enableSubmitButton();\r\n                 return false;\r\n              }\r\n\r\n           \r\n            // $j(\'.submitButton\').prop(\'disabled\', false);\r\n\r\n            var dataNascimento =  getDateOfBirth(); \r\n\r\n            var dataAberturaFicha = getParsedDate($j(\'#dataAberturaFicha input[type=text]\').attr(\'value\'));\r\n            validDateBeforeDOB(dataNascimento, dataAberturaFicha, \'data da abertura da ficha\');\r\n\r\n            var dataInicioPreTarv = getParsedDate($j(\'#dataInicioPreTarv input[type=text]\').attr(\'value\'));\r\n            validDateBeforeDOB(dataNascimento, dataInicioPreTarv, \'data início Pré-TARV\');\r\n\r\n            var dataTransferidoDe = getParsedDate($j(\'#dataTransferidoDe input[type=text]\').attr(\'value\')); \r\n            validDateBeforeDOB(dataNascimento, dataTransferidoDe, \'data de transferido de outra US\');\r\n\r\n            var dataDoCD4 = getParsedDate($j(\'#dataCD4 input[type=text]\').attr(\'value\'));\r\n            validDateBeforeDOB(dataNascimento, dataDoCD4, \'data  do último CD4\');\r\n\r\n            var dataDaCargaViral = getParsedDate($j(\'#dataCargaViral input[type=text]\').attr(\'value\'));\r\n            validDateBeforeDOB(dataNascimento, dataDaCargaViral, \'data da última carga viral\');          \r\n \r\n            if($j(\"#tptInicio input\").attr(\'checked\') === \'checked\'){\r\n\r\n                let dataTptInicio = getParsedDate($j(\'#tptInicio input[type=text]\').attr(\'value\'));\r\n                validDateBeforeDOB(dataNascimento, dataTptInicio, \'data início da última Profilaxia TPT\');\r\n            }\r\n            \r\n            if($j(\"#tptFim input\").attr(\'checked\') === \'checked\'){\r\n                \r\n                let dataTptFim = getParsedDate($j(\'#tptFim input[type=text]\').attr(\'value\'));\r\n                validDateBeforeDOB(dataNascimento, dataTptFim, \'data fim da última Profilaxia TPT\');\r\n            }\r\n\r\n            var dataInicioTarv = getParsedDate($j(\'#dataInicioTarv input[type=text]\').attr(\'value\'));\r\n            validDateBeforeDOB(dataNascimento, dataInicioTarv, \'data início TARV\'); \r\n\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia1 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia2 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia3 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia4 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia5 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n            validDateBeforeDOB(dataNascimento, getParsedDate($j(\"#idMudancaPermanencia6 input\")[0].value), \'data de Mudanças no Estado de Permanência TARV\');\r\n\r\n\r\n\r\n            if(!verifiyTPTDates()){\r\n                return false;\r\n            }\r\n\r\n            let dataCargaViral = document.getElementById(\'dataCargaViral\').getElementsByTagName(\'input\');\r\n            let valorCargaViral = dataCargaViral[0];\r\n\r\n            if( valorCargaViral.value !== \'\'  &amp;&amp; getValue(\'cargaViralNumeric.value\') === \'\'  &amp;&amp;  getValue(\'cargaViralSelection.value\') === \'\'){\r\n                alert(\'Informe a Última Carga Viral (cópias/ml)\');\r\n                enableSubmitButton();\r\n                    return false;\r\n            }\r\n\r\n            if (getValue(\'cargaViralNumeric.value\') !== \'\') {\r\n\r\n                if( valorCargaViral.value === \'\'){\r\n                    alert(\'Informe a data do resultado da última carga viral quantitativa\');\r\n                    enableSubmitButton();\r\n                    return false;\r\n                }\r\n                else {\r\n                    \r\n                    let cargaViralNumeric = document.getElementById(\'cargaViralNumeric\').getElementsByTagName(\'input\');\r\n                    let dataCargaViralNumeric = cargaViralNumeric[2];\r\n\r\n                    const [day, month, year] =  valorCargaViral.value.split(\'-\');\r\n                    dataCargaViralNumeric.value =  [year, month, day].join(\'-\'); \r\n                    $j(\'#dataCargaViral\').remove();                   \r\n                 }   \r\n            }\r\n\r\n            if (getValue(\'cargaViralSelection.value\') !== \'\') {\r\n\r\n\r\n                if (getValue(\'cargaViralSelection.value\') === \"165331\") {\r\n\r\n                    if($j(\'#cargaViralSelection input[type=number]\').attr(\'value\') === \'\'){\r\n                        alert(\'Informe o número de cópias/ml da última carga viral qualitativa\');\r\n                        enableSubmitButton();\r\n                        return false;\r\n                    }\r\n                }\r\n\r\n                if(valorCargaViral.value === \'\'){\r\n                    alert(\'Informe a data do resultado da última carga viral qualitativa\');\r\n                    enableSubmitButton();\r\n                    return false;\r\n                } \r\n                else{\r\n\r\n                    let cargaViralSelection = document.getElementById(\'cargaViralSelection\').getElementsByTagName(\'input\');\r\n                    let dataCargaViralSelection = cargaViralSelection[1];\r\n\r\n                    const [day, month, year] =  valorCargaViral.value.split(\'-\');\r\n                    dataCargaViralSelection.value =  [year, month, day].join(\'-\'); \r\n                    $j(\'#dataCargaViral\').remove();                   \r\n                }  \r\n            }  \r\n\r\n            let spanDataCD4Childs = document.getElementById(\'dataCD4\').getElementsByTagName(\'input\');\r\n            let inputDataCD4 = spanDataCD4Childs[0];\r\n\r\n            if( inputDataCD4.value !== \'\'  &amp;&amp; getValue(\'cd4Absoluto.value\') === \'\'  &amp;&amp;  getValue(\'cd4Percentual.value\') === \'\'  &amp;&amp;  getValue(\'cd4SemiQuantitativo.value\') === \'\'){\r\n                alert(\'Informe o valor do último CD4\');\r\n                    return false;\r\n            }\r\n\r\n            if(getValue(\'cd4Absoluto.value\') === \'\'){\r\n            let spanCD4AbsolutoChilds = document.getElementById(\'cd4Absoluto\').getElementsByTagName(\'input\');\r\n            let inputDataCD4Absoluto = spanCD4AbsolutoChilds[2];\r\n            inputDataCD4Absoluto.value = \'\';\r\n            }\r\n\r\n            if(getValue(\'cd4Percentual.value\') === \'\'){\r\n            let spanCD4PercentualChilds = document.getElementById(\'cd4Percentual\').getElementsByTagName(\'input\');\r\n            let inputDataCD4Percentual = spanCD4PercentualChilds[2];\r\n            inputDataCD4Percentual.value = \'\';\r\n            }\r\n\r\n\r\n            if(getValue(\'cd4SemiQuantitativo.value\') === \'\'){\r\n            let spanCD4SemiQuantitativeChilds = document.getElementById(\'cd4SemiQuantitativo\').getElementsByTagName(\'input\');\r\n            let inputDataCD4SemiQuantitative = spanCD4SemiQuantitativeChilds[1];\r\n            inputDataCD4SemiQuantitative.value = \'\';\r\n            }\r\n\r\n            if (getValue(\'cd4Absoluto.value\') !== \'\') {\r\n                if( inputDataCD4.value === \'\'){\r\n                    alert(\'Informe a data do resultado do último CD4\');\r\n                    enableSubmitButton();\r\n                    return false;\r\n                }\r\n                else {\r\n                    \r\n                    let spanDataCD4Childs = document.getElementById(\'cd4Absoluto\').getElementsByTagName(\'input\');\r\n                    let inputDataCD4Absoluto = spanDataCD4Childs[2];\r\n\r\n                    const [day, month, year] =  inputDataCD4.value.split(\'-\');\r\n                    inputDataCD4Absoluto.value =  [year, month, day].join(\'-\'); \r\n                    $j(\'#dataCD4\').remove();                   \r\n                 }   \r\n            }\r\n\r\n            if (getValue(\'cd4Percentual.value\') !== \'\') {\r\n                if( inputDataCD4.value === \'\'){\r\n                    alert(\'Informe a data do resultado do último CD4\');\r\n                    enableSubmitButton();\r\n                    return false;\r\n                }\r\n                else {\r\n                    \r\n                    let spanDataCD4Childs = document.getElementById(\'cd4Percentual\').getElementsByTagName(\'input\');\r\n                    let inputDataCd4Percentual = spanDataCD4Childs[2];\r\n\r\n                    const [day, month, year] =  inputDataCD4.value.split(\'-\');\r\n                    inputDataCd4Percentual.value =  [year, month, day].join(\'-\'); \r\n                    $j(\'#dataCD4\').remove();                   \r\n                 }   \r\n            }\r\n\r\n            if (getValue(\'cd4SemiQuantitativo.value\') !== \'\') {\r\n                if( inputDataCD4.value === \'\'){\r\n                    alert(\'Informe a data do resultado do último CD4\');\r\n                    enableSubmitButton();\r\n                    return false;\r\n                }\r\n                else {\r\n                    \r\n                    let spanDataCD4Childs = document.getElementById(\'cd4SemiQuantitativo\').getElementsByTagName(\'input\');\r\n                    let inputDataCd4Percentual = spanDataCD4Childs[1];\r\n\r\n                    const [day, month, year] =  inputDataCD4.value.split(\'-\');\r\n                    inputDataCd4Percentual.value =  [year, month, day].join(\'-\'); \r\n                    $j(\'#dataCD4\').remove();                   \r\n                 }   \r\n            } \r\n            \r\n            return true;\r\n        });\r\n         \r\n\r\n        function validDateBeforeDOB(dob, dateToValidate, message){\r\n\r\n            if(dateToValidate){\r\n\r\n                if (dateToValidate &lt;  dob) {\r\n                \r\n                    alert(\'A \'+message+\' [\'+dateToValidate.toLocaleDateString(\'pt-PT\')+\'] não deve ser menor que a data de nascimento\');\r\n                    enableSubmitButton();\r\n                }\r\n            }\r\n        }\r\n\r\n         function getParsedDate(dateToParse){\r\n\r\n            const [dayInicio, monthInicio, yearInicio] = dateToParse.split(\'-\');\r\n            let parsedDate = new Date(+yearInicio, +monthInicio-1, +dayInicio);\r\n            \r\n            return parsedDate;    \r\n        }\r\n\r\n        function getDateOfBirth(){\r\n\r\n            let year = \"<lookup expression=\"patient.birthdate.year\"/>\" ;\r\n            let month = \"<lookup expression=\"patient.birthdate.month\"/>\" ;\r\n            let day = \"<lookup expression=\"patient.birthdate.date\"/>\";\r\n \r\n            return new Date(parseInt(year) + 1900, parseInt(month), parseInt(day));    \r\n        }\r\n\r\n        function verifiyTPTDates() {\r\n            \r\n            var tptInicio = $j(\"#tptInicio input\");\r\n            var tptFim = $j(\"#tptFim input\");\r\n            var datesAreValidated = false;\r\n            var datesHaventErrors = true;\r\n\r\n            if (tptInicio.attr(\'checked\') === \'checked\') {\r\n\r\n                if($j(\'#tptInicio input[type=text]\').attr(\'value\') === \'\' ){\r\n                    getField(\'tptInicio.error\').html(\'Informe a data iInicio da última profilaxia TPT\').show();\r\n                    datesHaventErrors = false;\r\n                }\r\n            }\r\n\r\n            if (tptFim.attr(\'checked\') === \'checked\') {\r\n\r\n                if($j(\'#tptFim input[type=text]\').attr(\'value\') === \'\' ){\r\n                     getField(\'tptFim.error\').html(\'Informe a data fim da última profilaxia TPT\').show();\r\n                    datesHaventErrors = false;\r\n                }\r\n            }\r\n\r\n            if(datesHaventErrors){\r\n                if( tptInicio.attr(\'checked\') === \'checked\' || tptFim.attr(\'checked\') === \'checked\' ){\r\n                    var datesAreValidated = true;\r\n                }     \r\n            }\r\n            else{\r\n                return false;\r\n            }\r\n\r\n                \r\n            if( tptInicio.attr(\'checked\') === \'checked\' &amp;&amp; tptFim.attr(\'checked\') === \'checked\' &amp;&amp; datesAreValidated === true){\r\n\r\n                var dataInicioTPT  = $j(\'#tptInicio input[type=text]\').attr(\'value\');\r\n                var dataFimTPT     = $j(\'#tptFim input[type=text]\').attr(\'value\');\r\n                \r\n                const [dayInicio, monthInicio, yearInicio] = dataInicioTPT.split(\'-\');\r\n                const [dayFim, monthFim, yearFim] = dataFimTPT.split(\'-\');\r\n                \r\n                var dataInicioTPTDate = new Date(+yearInicio, +monthInicio-1, +dayInicio);\r\n                var dataFimTPTDate = new Date(+yearFim, +monthFim-1, +dayFim);\r\n   \r\n                if (dataFimTPTDate.getTime() &lt; dataInicioTPTDate.getTime()) {                                 \r\n                    alert(\'A data fim da última profilaxia TPT não deve ser menor que a data início da última profilaxia TPT\');    \r\n                    enableSubmitButton();             \r\n                }   \r\n            }\r\n            if (getValue(\'regimeTpt.value\') !== \'\'){\r\n\r\n                if( tptInicio.attr(\'checked\') !== \'checked\' &amp;&amp; tptFim.attr(\'checked\') !== \'checked\' ){\r\n                    \r\n                    var dataInicioTPT  = $j(\'#tptInicio input[type=text]\').attr(\'value\');\r\n                    var dataFimTPT     = $j(\'#tptFim input[type=text]\').attr(\'value\');\r\n\r\n                    if(dataInicioTPT !== \'\' || dataFimTPT !== \'\' ){\r\n                        alert(\'Selecione o checkbox para a data Início e/ou para a data fim da última profilaxia TPT\');\r\n                        enableSubmitButton();\r\n                    }\r\n                    else{\r\n                        alert(\'Indique a data Início e/ou a data fim da última profilaxia TPT\');\r\n                        enableSubmitButton();                    \r\n                    }\r\n                    return false;\r\n                }  \r\n            }\r\n\r\n            return true;\r\n        }\r\n\r\n    </script>            \r\n\r\n    <ifMode mode=\"VIEW\" include=\"false\">\r\n        <script type=\"text/javascript\">\r\n\r\n            $j(document).ready(function () {\r\n\r\n                 var nidTarv = \"<lookup expression=\"patient.getPatientIdentifier(2)\"/>\";\r\n\r\n                  if(validateNIDTarv(nidTarv) === false){\r\n                     window.alert(\'Este Paciente foi registado com um NID TARV inválido. Por favor corrija o NID para que esteja no formato padrão do NID TARV: CCPPDDUSSS/AAAA/NNNNN, onde o 9º e 10º dígitos (SS) devem ser 01, que representa o Código do Serviço TARV.\');   \r\n                  }\r\n\r\n                var estadoProgramaTarvConceptID = parseInt(\"<lookup expression=\"fn.currentProgramWorkflowStatus(2).state.concept.id\" />\");\r\n                if (isNaN(estadoProgramaTarvConceptID)) {\r\n                  window.alert(\'O Paciente não encontra-se registado como activo em Tratamento. Por favor, verifique e actualize o estado do paciente no módulo de inscrição do Programa \"Serviço TARV Tratamento\" como indicado.\');\r\n                    return false;\r\n                } else {\r\n                  if (((estadoProgramaTarvConceptID == 1707) || (estadoProgramaTarvConceptID == 1706) || (estadoProgramaTarvConceptID == 1709) || (estadoProgramaTarvConceptID == 1366))) {\r\n                    window.alert(\'O Paciente não encontra-se registado como activo em Tratamento. Por favor, verifique e actualize o estado do paciente no módulo de inscrição do Programa \"Serviço TARV Tratamento\" como indicado.\');\r\n                      return false;\r\n                  }\r\n                }\r\n            });\r\n\r\n             function validateNIDTarv(inputNID) {\r\n                var pattern = /^\\(?([0-9]{8})\\)?([0])([1])([/])([0-9]{4})([/])([0-9]{5})$/;\r\n                return pattern.test(inputNID);\r\n                }\r\n        </script>\r\n    </ifMode>\r\n           \r\n    <ifMode mode=\"VIEW\" include=\"false\">\r\n      <script type=\"text/javascript\">\r\n\r\n          $j(window).on(\'load\', function() {\r\n\r\n           var text2 = $j(\"#regimeTpt\").find(\"span:first\").text();\r\n\r\n          if (text2 === \'____________\') {\r\n          $j(\'#tInicio\').remove();\r\n          $j(\'#tFim\').remove();\r\n          $j(\'#proflaxia\').remove();\r\n          $j(\'#iInicio\').css(\'display\', \'block\');\r\n          $j(\'#iFim\').css(\'display\', \'block\');\r\n          } else {\r\n          $j(\'#tInicio\').css(\'display\', \'block\');\r\n          $j(\'#tFim\').css(\'display\', \'block\');\r\n          $j(\'#proflaxia\').css(\'display\', \'block\');\r\n          $j(\'#iInicio\').remove();\r\n          $j(\'#iFim\').remove();\r\n          window.onload = disableTptDates();\r\n          }\r\n      });  \r\n\r\n      </script>\r\n    </ifMode>\r\n\r\n\r\n <ifMode mode=\"VIEW\" include=\"false\">\r\n    <script type=\"text/javascript\">\r\n        jQuery(function () {\r\n        getField(\'cargaViralNumeric.value\').change(function () {\r\n          if (getValue(\'cargaViralNumeric.value\') === \"\") {\r\n            $j(\"#cargaViralSelection select\").attr(\'disabled\', false);\r\n            $j(\"#cargaViralSelection input\").attr(\'disabled\', false);\r\n          }\r\n          else {\r\n            $j(\"#cargaViralSelection select\").attr(\'disabled\', true);\r\n            $j(\"#cargaViralSelection input\").attr(\'disabled\', true);\r\n          }\r\n        })\r\n        getField(\'cargaViralSelection.value\').change(function () {\r\n          if (getValue(\'cargaViralSelection.value\') === \"\") {\r\n            $j(\"#cargaViralNumeric input\").attr(\'disabled\', false);\r\n          }\r\n          else {\r\n            $j(\"#cargaViralNumeric input\").attr(\'disabled\', true);\r\n          }\r\n        })\r\n\r\n      });\r\n\r\n        jQuery(function () {\r\n        getField(\'cargaViralSelection.value\').change(function () {\r\n        var childInputs = document.getElementById(\'cargaViralSelection\').getElementsByTagName(\'input\');\r\n        var idInput = childInputs[2].id;\r\n        if (getValue(\'cargaViralSelection.value\') === \"165331\") {\r\n            document.getElementById(idInput).disabled = false;\r\n          }\r\n          else {\r\n             document.getElementById(idInput).disabled = true;\r\n             document.getElementById(idInput).value = \'\';\r\n          }\r\n        })\r\n      });\r\n\r\n         document.addEventListener(\"DOMContentLoaded\", function () {\r\n\r\n        if (getValue(\'cargaViralNumeric.value\') === \"\") {\r\n            $j(\"#cargaViralSelection select\").attr(\'disabled\', false);\r\n            $j(\"#cargaViralSelection input\").attr(\'disabled\', false);\r\n          }\r\n          else {\r\n            $j(\"#cargaViralSelection select\").attr(\'disabled\', true);\r\n            $j(\"#cargaViralSelection input\").attr(\'disabled\', true);\r\n          }\r\n\r\n          if (getValue(\'cargaViralSelection.value\') === \"\") {\r\n            $j(\"#cargaViralNumeric input\").attr(\'disabled\', false);\r\n          }\r\n          else {\r\n            $j(\"#cargaViralNumeric input\").attr(\'disabled\', true);\r\n          }\r\n        var childInputs = document.getElementById(\'cargaViralSelection\').getElementsByTagName(\'input\');\r\n        var idInput = childInputs[2].id;\r\n        document.getElementById(idInput).setAttribute(\'type\', \'number\');\r\n\r\n        $j(\'#\'+idInput).on(\'input\', function() {\r\n          this.value = this.value=this.value.replace(/\\D/g,\'\').replace(/^0+(?=\\d)/,\'\');\r\n        });\r\n        \r\n        if(getValue(\'cargaViralSelection.value\') === \"165331\"){\r\n             document.getElementById(idInput).disabled = false;\r\n         }else{\r\n             document.getElementById(idInput).disabled = true;\r\n         }\r\n\r\n         if (getValue(\'cd4Percentual.value\') === \"\" &amp;&amp; getValue(\'cd4Absoluto.value\') === \"\") {\r\n                $j(\"#cd4SemiQuantitativo select\").attr(\'disabled\', false);\r\n                $j(\"#cd4SemiQuantitativo input\").attr(\'disabled\', false);\r\n              }\r\n              else {\r\n                $j(\"#cd4SemiQuantitativo select\").attr(\'disabled\', true);\r\n                $j(\"#cd4SemiQuantitativo input\").attr(\'disabled\', true);\r\n                $j(\"#cd4SemiQuantitativo input\").attr(\'value\', \'\');\r\n              }\r\n\r\n              \r\n              if (getValue(\'cd4SemiQuantitativo.value\') === \"\") {\r\n                $j(\"#cd4Absoluto input\").attr(\'disabled\', false);\r\n                $j(\"#cd4Percentual input\").attr(\'disabled\', false);\r\n              }\r\n              else {\r\n                $j(\"#cd4Absoluto input\").attr(\'disabled\', true);\r\n                $j(\"#cd4Percentual input\").attr(\'disabled\', true);\r\n                $j(\"#cd4Absoluto input\").attr(\'value\', \'\');\r\n                $j(\"#cd4Percentual input\").attr(\'value\', \'\');\r\n              }\r\n\r\n            if (getValue(\'cd4PercentualInicioTarv.value\') === \"\" &amp;&amp; getValue(\'cd4AbsolutoInicioTarv.value\') === \"\") {\r\n                $j(\"#cd4SemiQuantitativoInicioTarv select\").attr(\'disabled\', false);\r\n                $j(\"#cd4SemiQuantitativoInicioTarv input\").attr(\'disabled\', false);\r\n              }\r\n              else {\r\n                $j(\"#cd4SemiQuantitativoInicioTarv select\").attr(\'disabled\', true);\r\n                $j(\"#cd4SemiQuantitativoInicioTarv input\").attr(\'disabled\', true);\r\n                $j(\"#cd4SemiQuantitativoInicioTarv input\").attr(\'value\', \'\');\r\n              }\r\n\r\n              \r\n              if (getValue(\'cd4SemiQuantitativoInicioTarv.value\') === \"\") {\r\n                $j(\"#cd4AbsolutoInicioTarv input\").attr(\'disabled\', false);\r\n                $j(\"#cd4PercentualInicioTarv input\").attr(\'disabled\', false);\r\n              }\r\n              else {\r\n                $j(\"#cd4AbsolutoInicioTarv input\").attr(\'disabled\', true);\r\n                $j(\"#cd4PercentualInicioTarv input\").attr(\'disabled\', true);\r\n                $j(\"#cd4AbsolutoInicioTarv input\").attr(\'value\', \'\');\r\n                $j(\"#cd4PercentualInicioTarv input\").attr(\'value\', \'\');\r\n              }\r\n      });\r\n     \r\n  </script>\r\n</ifMode>\r\n\r\n</head>\r\n<body>\r\n    \r\n        <div class=\"main\">\r\n            \r\n            <div class=\"header-box\">\r\n                <h2>FICHA RESUMO</h2>\r\n            </div>\r\n    \r\n            <div class=\"content\">\r\n    \r\n                    <div class=\"header\">\r\n    \r\n                        <div class=\"header-data\">\r\n                                <p>\r\n                                <label>Nome:</label>\r\n                                <lookup expression=\"patient.personName\"/>\r\n                 